mapper.select:
SELECT id FROM user_reading_subscription
WHERE auto_renew=1 AND status IN ('ACTIVE', 'PAST_DUE')
  AND next_renewal_at<=#{now}
ORDER BY next_renewal_at ASC, id ASC LIMIT #{limit}

SELECT id FROM reading_subscription_renewal_cycle
WHERE status IN ('DUE', 'RETRY_WAIT') AND next_attempt_at<=#{now}
ORDER BY next_attempt_at ASC, id ASC LIMIT #{limit}
